def cancel_pending_order(order_id, reason, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0177000" if __import__("os").path.isdir("./environment_mix/0177000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "cancel_pending_order"

    def _log(status, code=None, message=None):
        usage = _load("usage.json")
        if not isinstance(usage, list):
            usage = []
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        usage.append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "ts": now,
                "endpoint": endpoint,
                "status": status,
                "error_code": code,
                "error_message": message,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        )
        _save("usage.json", usage)

    try:
        if not isinstance(order_id, str) or not order_id.strip():
            _log("error", "VALIDATION_ERROR", "order_id must be a non-empty string")
            return _err("VALIDATION_ERROR", "order_id must be a non-empty string")
        if not order_id.startswith("#"):
            _log("error", "VALIDATION_ERROR", "order_id must start with '#'")
            return _err("VALIDATION_ERROR", "order_id must start with '#'")
        if reason not in ("no longer needed", "ordered by mistake"):
            _log("error", "VALIDATION_ERROR", "Invalid reason")
            return _err("VALIDATION_ERROR", "Invalid reason", allowed=["no longer needed", "ordered by mistake"])

        orders = _load("orders.json")
        if not isinstance(orders, list):
            orders = []

        idx = None
        for i, o in enumerate(orders):
            if isinstance(o, dict) and o.get("order_id") == order_id:
                idx = i
                break
        if idx is None:
            _log("error", "NOT_FOUND", "Order not found")
            return _err("NOT_FOUND", "Order not found")

        order = orders[idx]
        status = order.get("status")
        if status == "cancelled":
            _log("error", "INVALID_TRANSITION", "Order is already cancelled")
            return _err("INVALID_TRANSITION", "Order is already cancelled")
        if status != "pending":
            _log("error", "INVALID_TRANSITION", "Only pending orders can be cancelled")
            return _err("INVALID_TRANSITION", "Only pending orders can be cancelled", current_status=status, allowed_from=["pending"])

        # Apply cancellation and record refund transactions mirroring prior payments
        ph = order.get("payment_history")
        if ph is None:
            ph = []
        if not isinstance(ph, list):
            _log("error", "VALIDATION_ERROR", "order.payment_history must be an array")
            return _err("VALIDATION_ERROR", "order.payment_history must be an array")

        refunds = []
        for p in ph:
            if not isinstance(p, dict):
                continue
            if p.get("transaction_type") == "payment":
                amt = p.get("amount")
                pmid = p.get("payment_method_id")
                if isinstance(amt, (int, float)) and isinstance(pmid, str) and pmid:
                    refunds.append({"transaction_type": "refund", "amount": float(amt), "payment_method_id": pmid})

        # Update user gift card balances for refunds (best-effort; if user/method missing, still cancel order)
        users = _load("users.json")
        if not isinstance(users, list):
            users = []
        user_id = order.get("user_id")
        user_row = None
        if isinstance(user_id, str):
            for u in users:
                if isinstance(u, dict) and u.get("id") == user_id:
                    user_row = u
                    break

        if user_row is not None:
            pms = user_row.get("payment_methods")
            # store shape may be object or list; handle both
            for r in refunds:
                pmid = r.get("payment_method_id")
                amt = r.get("amount", 0.0)
                if not (isinstance(pmid, str) and pmid and isinstance(amt, (int, float))):
                    continue
                if isinstance(pms, list):
                    for pm in pms:
                        if isinstance(pm, dict) and pm.get("id") == pmid and pm.get("source") == "gift_card":
                            bal = pm.get("balance", 0)
                            if isinstance(bal, int):
                                pm["balance"] = bal + int(round(float(amt)))
                            elif isinstance(bal, float):
                                pm["balance"] = round(bal + float(amt), 2)
                            else:
                                pm["balance"] = round(float(amt), 2)
                            break
                elif isinstance(pms, dict):
                    pm = pms.get(pmid)
                    if isinstance(pm, dict) and pm.get("source") == "gift_card":
                        bal = pm.get("balance", 0)
                        if isinstance(bal, int):
                            pm["balance"] = bal + int(round(float(amt)))
                        elif isinstance(bal, float):
                            pm["balance"] = round(bal + float(amt), 2)
                        else:
                            pm["balance"] = round(float(amt), 2)

        order["status"] = "cancelled"
        order["cancel_reason"] = reason
        order["payment_history"] = ph + refunds
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        order["updated_at"] = now
        if "created_at" not in order:
            order["created_at"] = now

        orders[idx] = order
        _save("orders.json", orders)
        if user_row is not None:
            _save("users.json", users)

        _log("success")
        return {"order": order}
    except Exception as e:
        _log("error", "VALIDATION_ERROR", str(e))
        return _err("VALIDATION_ERROR", "Request could not be processed", detail=str(e))

