def list_all_product_types(limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0177000" if __import__("os").path.isdir("./environment_mix/0177000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_all_product_types"

    def _log(status, code=None, message=None):
        usage = _load("usage.json")
        if not isinstance(usage, list):
            usage = []
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        usage.append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "ts": now,
                "endpoint": endpoint,
                "status": status,
                "error_code": code,
                "error_message": message,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        )
        _save("usage.json", usage)

    try:
        if limit is None:
            limit = 50
        if not isinstance(limit, int):
            _log("error", "VALIDATION_ERROR", "limit must be an integer")
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 50:
            _log("error", "VALIDATION_ERROR", "limit out of range")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 50")

        start = 0
        if cursor is not None:
            if not isinstance(cursor, str) or not cursor:
                _log("error", "VALIDATION_ERROR", "cursor must be a non-empty string when provided")
                return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
            # cursor format: base64("v1:<start>:<date>")
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            except Exception:
                _log("error", "VALIDATION_ERROR", "Invalid cursor")
                return _err("VALIDATION_ERROR", "Invalid cursor")
            parts = raw.split(":")
            if len(parts) < 2 or parts[0] != "v1":
                _log("error", "VALIDATION_ERROR", "Invalid cursor")
                return _err("VALIDATION_ERROR", "Invalid cursor")
            try:
                start = int(parts[1])
            except Exception:
                _log("error", "VALIDATION_ERROR", "Invalid cursor")
                return _err("VALIDATION_ERROR", "Invalid cursor")
            if start < 0:
                _log("error", "VALIDATION_ERROR", "Invalid cursor")
                return _err("VALIDATION_ERROR", "Invalid cursor")

        products = _load("products.json")
        if not isinstance(products, list):
            products = []

        rows = []
        for p in products:
            if not isinstance(p, dict):
                continue
            name = p.get("name")
            pid = p.get("product_id")
            if isinstance(name, str) and isinstance(pid, str):
                rows.append({"name": name, "product_id": pid})

        # stable ordering
        rows.sort(key=lambda r: (r.get("name") or "", r.get("product_id") or ""))

        total = len(rows)
        if start > total:
            _log("error", "VALIDATION_ERROR", "Invalid/expired cursor")
            return _err("VALIDATION_ERROR", "Invalid/expired cursor")

        page = rows[start : start + limit]
        next_start = start + len(page)
        has_more = next_start < total
        next_cursor = None
        if has_more:
            payload = f"v1:{next_start}:{datetime.datetime.utcnow().date().isoformat()}"
            next_cursor = base64.urlsafe_b64encode(payload.encode("utf-8")).decode("utf-8")

        _log("success")
        return {"data": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}
    except Exception as e:
        _log("error", "VALIDATION_ERROR", str(e))
        return _err("VALIDATION_ERROR", "Request could not be processed", detail=str(e))

