        if not isinstance(usage, list):
            usage = []
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        usage.append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "ts": now,
                "endpoint": endpoint,
                "status": status,
                "error_code": code,
                "error_message": message,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        )
        _save("usage.json", usage)

    try:
        if not isinstance(order_id, str) or not order_id.strip() or not order_id.startswith("#"):
            _log("error", "VALIDATION_ERROR", "Invalid order_id")
            return _err("VALIDATION_ERROR", "Invalid order_id")
        if not (isinstance(item_ids, list) and all(isinstance(x, str) for x in item_ids)):
            _log("error", "VALIDATION_ERROR", "item_ids must be an array of strings")
            return _err("VALIDATION_ERROR", "item_ids must be an array of strings")
        if not (isinstance(new_item_ids, list) and all(isinstance(x, str) for x in new_item_ids)):
            _log("error", "VALIDATION_ERROR", "new_item_ids must be an array of strings")
            return _err("VALIDATION_ERROR", "new_item_ids must be an array of strings")
        if len(item_ids) != len(new_item_ids):
            _log("error", "VALIDATION_ERROR", "item_ids and new_item_ids must have the same length")
            return _err("VALIDATION_ERROR", "item_ids and new_item_ids must have the same length")
        if not isinstance(payment_method_id, str) or not payment_method_id.strip():
            _log("error", "VALIDATION_ERROR", "payment_method_id must be a non-empty string")
            return _err("VALIDATION_ERROR", "payment_method_id must be a non-empty string")

        orders = _load("orders.json")
        if not isinstance(orders, list):
            orders = []
        products = _load("products.json")
        if not isinstance(products, list):
            products = []
        users = _load("users.json")
        if not isinstance(users, list):
            users = []

        # Find order
        idx = None
        for i, o in enumerate(orders):
            if isinstance(o, dict) and o.get("order_id") == order_id:
                idx = i
                break
        if idx is None:
            _log("error", "NOT_FOUND", "Order not found")
            return _err("NOT_FOUND", "Order not found")
        order = orders[idx]

        if order.get("status") != "pending":
            _log("error", "INVALID_TRANSITION", "Only pending orders can be modified")
            return _err("INVALID_TRANSITION", "Only pending orders can be modified", current_status=order.get("status"), allowed_from=["pending"])

        if order.get("items_modified_once") is True:
            _log("error", "INVALID_TRANSITION", "Order items have already been modified once")
            return _err("INVALID_TRANSITION", "Order items have already been modified once")

        order_items = order.get("items")
        if not isinstance(order_items, list):
            _log("error", "VALIDATION_ERROR", "order.items must be an array")
            return _err("VALIDATION_ERROR", "order.items must be an array")

        # Count occurrences for duplicates
        from collections import Counter
        have = Counter([it.get("item_id") for it in order_items if isinstance(it, dict)])
        want = Counter(item_ids)
        for k, v in want.items():
            if have.get(k, 0) < v:
                _log("error", "NOT_FOUND", f"Item id {k} not found on order")
                return _err("NOT_FOUND", f"Item id {k} not found on order", item_id=k)

        # Index products/variants for lookup in list-shaped store
        prod_by_id = {}
        for p in products:
            if isinstance(p, dict) and isinstance(p.get("product_id"), str):
                prod_by_id[p["product_id"]] = p

        # Validate payment method belongs to user
        user_id = order.get("user_id")
        user_row = None
        if isinstance(user_id, str):
            for u in users:
                if isinstance(u, dict) and u.get("id") == user_id:
                    user_row = u
                    break
        if user_row is None:
            _log("error", "NOT_FOUND", "User for order not found")
            return _err("NOT_FOUND", "User for order not found")

        pms = user_row.get("payment_methods")
        pm_row = None
        if isinstance(pms, list):
            for pm in pms:
                if isinstance(pm, dict) and pm.get("id") == payment_method_id:
                    pm_row = pm
                    break
        elif isinstance(pms, dict):
            cand = pms.get(payment_method_id)
            if isinstance(cand, dict):
                pm_row = cand
        if pm_row is None:
            _log("error", "NOT_FOUND", "Payment method not found for user")
            return _err("NOT_FOUND", "Payment method not found for user")

        # Build replacement plan: replace occurrences in order_items in the order given
        # For each pair, find next matching item to replace.
        diff_price = 0.0
        replace_indices = []
        used_positions = set()
        for old_id, new_id in zip(item_ids, new_item_ids):
            found_j = None
            for j, it in enumerate(order_items):
                if j in used_positions:
                    continue
                if isinstance(it, dict) and it.get("item_id") == old_id:
                    found_j = j
                    break
            if found_j is None:
                _log("error", "NOT_FOUND", f"Item id {old_id} not found on order")
                return _err("NOT_FOUND", f"Item id {old_id} not found on order", item_id=old_id)
            used_positions.add(found_j)

            it = order_items[found_j]
            product_id = it.get("product_id")
            if not isinstance(product_id, str) or product_id not in prod_by_id:
                _log("error", "NOT_FOUND", "Product for order item not found")
                return _err("NOT_FOUND", "Product for order item not found", product_id=product_id)

            product = prod_by_id[product_id]
            variants = product.get("variants")
            # variants in schema is object; in practice might be list or dict
            new_variant = None
            if isinstance(variants, dict):
                new_variant = variants.get(new_id)
                # sometimes dict of item_id->variant
            elif isinstance(variants, list):
                for v in variants:
                    if isinstance(v, dict) and v.get("item_id") == new_id:
                        new_variant = v
                        break
            else:
                new_variant = None

            if not isinstance(new_variant, dict):
                _log("error", "NOT_FOUND", "New item id not found for product")
                return _err("NOT_FOUND", "New item id not found for product", new_item_id=new_id, product_id=product_id)

            if new_variant.get("available") is False:
                _log("error", "CONFLICT", "New item is not available")
                return _err("CONFLICT", "New item is not available", new_item_id=new_id)

            old_price = it.get("price")
            new_price = new_variant.get("price")
            if not isinstance(old_price, (int, float)) or not isinstance(new_price, (int, float)):
                _log("error", "VALIDATION_ERROR", "Missing/invalid price for item exchange")
                return _err("VALIDATION_ERROR", "Missing/invalid price for item exchange")

            diff_price += float(new_price) - float(old_price)
            replace_indices.append((found_j, new_variant))

        # Ensure gift card has enough balance if payment is needed
        if diff_price > 0 and pm_row.get("source") == "gift_card":
            bal = pm_row.get("balance", 0)
            if not isinstance(bal, (int, float)) or float(bal) < diff_price - 1e-9:
                _log("error", "CONFLICT", "Insufficient gift card balance")
                return _err("CONFLICT", "Insufficient gift card balance")

        # Apply replacements
        for j, new_variant in replace_indices:
            it = order_items[j]
            product_id = it.get("product_id")
            # keep name/product_id, swap item_id/options/price from variant if present
            it["item_id"] = new_variant.get("item_id", it.get("item_id"))
            if "options" in new_variant:
                it["options"] = new_variant.get("options")
            if isinstance(new_variant.get("price"), (int, float)):
                it["price"] = float(new_variant["price"])
            if isinstance(product_id, str):
                it["product_id"] = product_id
            order_items[j] = it

        # Record payment history adjustment if diff != 0
        ph = order.get("payment_history")
        if ph is None:
            ph = []
        if not isinstance(ph, list):
            _log("error", "VALIDATION_ERROR", "order.payment_history must be an array")
            return _err("VALIDATION_ERROR", "order.payment_history must be an array")

        if abs(diff_price) > 1e-9:
            ph.append(
                {
                    "transaction_type": "payment" if diff_price > 0 else "refund",
                    "amount": round(abs(diff_price), 2),
                    "payment_method_id": payment_method_id,
                }
            )

            # adjust gift card balance when used
            if pm_row.get("source") == "gift_card":
                bal = pm_row.get("balance", 0)
                if isinstance(bal, int):
                    pm_row["balance"] = bal - int(round(diff_price)) if diff_price > 0 else bal + int(round(-diff_price))
                else:
                    pm_row["balance"] = round(float(bal) - diff_price, 2)

        order["items"] = order_items
        order["payment_history"] = ph
        order["items_modified_once"] = True
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        order["updated_at"] = now
        if "created_at" not in order:
            order["created_at"] = now

        orders[idx] = order
        _save("orders.json", orders)
        _save("users.json", users)

        _log("success")
        return {"order": order, "price_difference": round(diff_price, 2)}
    except Exception as e:
        _log("error", "VALIDATION_ERROR", str(e))
        return _err("VALIDATION_ERROR", "Request could not be processed", detail=str(e))

