                "id": "req_" + uuid.uuid4().hex,
                "ts": now,
                "endpoint": endpoint,
                "status": status,
                "error_code": code,
                "error_message": message,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        )
        _save("usage.json", usage)

    try:
        if not isinstance(summary, str) or not summary.strip():
            _log("error", "VALIDATION_ERROR", "summary must be a non-empty string")
            return _err("VALIDATION_ERROR", "summary must be a non-empty string")
        if len(summary) > 4000:
            _log("error", "VALIDATION_ERROR", "summary is too long")
            return _err("VALIDATION_ERROR", "summary is too long", max_length=4000)

        # Create a handoff record. If the system disallows in some contexts, we'd return UNAUTHORIZED/CONFLICT,
        # but there is no context store here; always allow.
        handoffs = _load("handoffs.json")
        if not isinstance(handoffs, list):
            handoffs = []
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        rec = {"id": "handoff_" + uuid.uuid4().hex, "ts": now, "summary": summary, "status": "queued"}
        handoffs.append(rec)
        _save("handoffs.json", handoffs)

        _log("success")
        return {"handoff": rec, "message": "Conversation handed off to a human agent"}
    except Exception as e:
        _log("error", "VALIDATION_ERROR", str(e))
        return _err("VALIDATION_ERROR", "Request could not be processed", detail=str(e))
